definitions/artifacts/functions/general/.content:
{
    "id": "getSellerSaleEnrollment",
    "method": "GET",
    "access": {
        "mode": "auth"
    },
    "meta": {
        "name": "Get seller sale enrollment",
        "description": "Return the authenticated Commerce seller and independent Stripe account, terms, transfer, bank, and payout states, including whether the configured seller terms are accepted."
    },
    "input": {
        "params": []
    },
    "output": {
        "$include": "output/root.json"
    },
    "steps": [
        {
            "id": "connect",
            "call": {
                "source": "{{dependencies.stripe.sourceId}}",
                "endpoint": "getConnectStatus",
                "params": {
                    "marketplaceTermsVersion": "{{answers.sellerTermsVersion}}",
                    "marketplaceTermsHash": "{{answers.sellerTermsHash}}"
                }
            }
        },
        {
            "id": "seller",
            "call": {
                "source": "{{dependencies.commerce.sourceId}}",
                "endpoint": "mySeller"
            }
        },
        {
            "assert": {
                "condition": {
                    "all": [
                        {
                            "equals": [
                                "$steps.connect.userId",
                                "$ctx.user.id"
                            ]
                        },
                        {
                            "any": [
                                {
                                    "equals": [
                                        "$steps.seller.exists",
                                        false
                                    ]
                                },
                                {
                                    "equals": [
                                        "$steps.seller.cmsUserId",
                                        "$ctx.user.id"
                                    ]
                                }
                            ]
                        }
                    ]
                },
                "failure": {
                    "status": 403,
                    "error": "Seller enrollment identity mismatch"
                }
            }
        }
    ],
    "return": {
        "status": 200,
        "body": {
            "connect": "$steps.connect",
            "seller": "$steps.seller"
        }
    }
}

definitions/artifacts/functions/offers/s.content:
{
    "id": "submitSellerOfferPrice",
    "method": "POST",
    "access": {
        "mode": "auth"
    },
    "meta": {
        "name": "Submit seller offer price",
        "description": "Idempotently enroll the authenticated seller for held platform payments with explicit current seller-terms consent when necessary, then submit the price to Commerce without promoting Commerce verification or requiring a bank payout rail."
    },
    "input": {
        "body": {
            "type": "object",
            "properties": {
                "offerId": {
                    "type": "string"
                },
                "amount": {
                    "type": "number"
                },
                "expectedVersion": {
                    "type": "number"
                },
                "accountToken": {
                    "type": "string"
                },
                "sellerTermsAccepted": {
                    "type": "boolean"
                },
                "sellerTermsVersion": {
                    "type": "string"
                },
                "sellerTermsHash": {
                    "type": "string"
                }
            },
            "required": [
                "offerId",
                "amount",
                "expectedVersion"
            ]
        }
    },
    "output": [
        {
            "status": "200",
            "body": {
                "type": "object",
                "properties": {
                    "offer": {
                        "type": "object"
                    },
                    "proposal": {
                        "type": "object"
                    }
                },
                "required": [
                    "offer",
                    "proposal"
                ]
            }
        },
        {
            "status": "400",
            "body": {
                "type": "object",
                "properties": {
                    "error": {
                        "type": "string"
                    }
                },
                "required": [
                    "error"
                ]
            }
        },
        {
            "status": "403",
            "body": {
                "type": "object",
                "properties": {
                    "error": {
                        "type": "string"
                    }
                },
                "required": [
                    "error"
                ]
            }
        },
        {
            "status": "409",
            "body": {
                "type": "object",
                "properties": {
                    "error": {
                        "type": "string"
                    }
                },
                "required": [
                    "error"
                ]
            }
        }
    ],
    "steps": {
        "$include": "steps/root.json"
    },
    "return": {
        "status": 200,
        "body": "$steps.result"
    }
}

[
    {
        "id": "seller",
        "call": {
            "source": "{{dependencies.commerce.sourceId}}",
            "endpoint": "getCurrentSellerIdentity"
        }
    },
    {
        "id": "connect",
        "call": {
            "source": "{{dependencies.stripe.sourceId}}",
            "endpoint": "getConnectStatus",
            "params": {
                "marketplaceTermsVersion": "{{answers.sellerTermsVersion}}",
                "marketplaceTermsHash": "{{answers.sellerTermsHash}}"
            }
        }
    },
    {
        "assert": {
            "condition": {
                "all": [
                    {
                        "equals": [
                            "$steps.seller.exists",
                            true
                        ]
                    },
                    {
                        "equals": [
                            "$steps.seller.cmsUserId",
                            "$ctx.user.id"
                        ]
                    },
                    {
                        "equals": [
                            "$steps.connect.userId",
                            "$ctx.user.id"
                        ]
                    }
                ]
            },
            "failure": {
                "status": 403,
                "error": "Seller enrollment identity mismatch"
            }
        }
    },
    {
        "assert": {
            "condition": {
                "any": [
                    {
                        "equals": [
                            "$steps.connect.marketplaceTermsCurrentVersionAccepted",
                            true
                        ]
                    },
                    {
                        "equals": [
                            "$input.body.sellerTermsAccepted",
                            true
                        ]
                    }
                ]
            },
            "failure": {
                "status": 409,
                "error": "The current seller terms must be accepted before submitting a price"
            }
        }
    },
    {
        "assert": {
            "condition": {
                "any": [
                    {
                        "equals": [
                            "$steps.connect.accountStatus",
                            "active"
                        ]
                    },
                    {
                        "exists": "$input.body.accountToken"
                    }
                ]
            },
            "failure": {
                "status": 409,
                "error": "Seller enrollment is required before submitting a price"
            }
        }
    },
    {
        "id": "enrollment",
        "call": {
            "source": "{{dependencies.stripe.sourceId}}",
            "endpoint": "enrollConnectSeller",
            "body": {
                "accountToken": "$input.body.accountToken",
                "marketplaceTermsAccepted": "$input.body.sellerTermsAccepted",
                "marketplaceTermsVersion": "{{answers.sellerTermsVersion}}",
                "marketplaceTermsHash": "{{answers.sellerTermsHash}}",
                "expectedMarketplaceTermsVersion": "$input.body.sellerTermsVersion",
                "expectedMarketplaceTermsHash": "$input.body.sellerTermsHash"
            }
        }
    },
    {
        "id": "saleCapability",
        "call": {
            "source": "{{dependencies.commerce.sourceId}}",
            "endpoint": "recordSellerSaleCapability",
            "body": {
                "sellerCmsUserId": "$ctx.user.id",
                "capabilityKey": "protected_payment",
                "ready": "$steps.enrollment.canAcceptHeldPayments",
                "evidenceReference": "stripe-connect:enrollment"
            }
        }
    },
    {
        "$include": "validate-seller-enrollment-not-ready-held-payments.json"
    },
    {
        "id": "result",
        "call": {
            "source": "{{dependencies.commerce.sourceId}}",
            "endpoint": "submitMyOfferPrice",
            "params": {
                "id": "$input.body.offerId"
            },
            "body": {
                "amount": "$input.body.amount",
                "expectedVersion": "$input.body.expectedVersion"
            }
        }
    }
]

{
    "assert": {
        "condition": {
            "all": [
                {
                    "equals": [
                        "$steps.enrollment.userId",
                        "$ctx.user.id"
                    ]
                },
                {
                    "equals": [
                        "$steps.enrollment.accountStatus",
                        "active"
                    ]
                },
                {
                    "equals": [
                        "$steps.enrollment.termsStatus",
                        "accepted"
                    ]
                },
                {
                    "equals": [
                        "$steps.enrollment.stripeTermsStatus",
                        "accepted"
                    ]
                },
                {
                    "equals": [
                        "$steps.enrollment.marketplaceTermsStatus",
                        "accepted"
                    ]
                },
                {
                    "equals": [
                        "$steps.enrollment.marketplaceTermsCurrentVersionAccepted",
                        true
                    ]
                },
                {
                    "equals": [
                        "$steps.enrollment.enrollmentStatus",
                        "enrolled"
                    ]
                },
                {
                    "equals": [
                        "$steps.enrollment.canAcceptHeldPayments",
                        true
                    ]
                }
            ]
        },
        "failure": {
            "status": 409,
            "error": "Seller enrollment is not ready for held payments"
        }
    }
}

