            "run": "$steps.providerRun",
            "paymentProjections": "$steps.paymentProjections",
            "operationProjections": "$steps.operationProjections",
            "disputeProjections": "$steps.disputeProjections"
        }
    }
}

[
    {
        "id": "operationProjections",
        "forEach": {
            "items": "$steps.providerRun.commerceOperations",
            "max": 5,
            "continueOnError": true,
            "steps": [
                {
                    "id": "commerceOperation",
                    "call": {
                        "source": "{{dependencies.commerce.sourceId}}",
                        "endpoint": "recordOrderSettlement",
                        "body": {
                            "orderPublicId": "$item.orderPublicId",
                            "providerEventId": "$item.providerEventId",
                            "operationType": "$item.operationType",
                            "providerOperationId": "$item.providerOperationId",
                            "status": "$item.status",
                            "amount": "$item.amount",
                            "currency": "$item.currency",
                            "occurredAt": "$item.occurredAt",
                            "releaseAuthorizationId": "$item.releaseAuthorizationId",
                            "refundRequestId": "$item.refundRequestId",
                            "commerceRefundRequestId": "$item.commerceRefundRequestId",
                            "providerSnapshot": "$item.providerSnapshot"
                        }
                    }
                },
                {
                    "id": "acknowledgeProjection",
                    "call": {
                        "source": "{{dependencies.stripe.sourceId}}",
                        "endpoint": "acknowledgeCommerceProjection",
                        "body": {
                            "projectionId": "$item.projectionId",
                            "claimToken": "$item.projectionClaimToken"
                        }
                    }
                }
            ],
            "yield": "$steps.commerceOperation",
            "onError": [
                {
                    "id": "failProjection",
                    "call": {
                        "source": "{{dependencies.stripe.sourceId}}",
                        "endpoint": "failCommerceProjection",
                        "body": {
                            "projectionId": "$item.projectionId",
                            "claimToken": "$item.projectionClaimToken",
                            "error": "Commerce financial projection failed"
                        }
                    }
                }
            ],
            "errorYield": {
                "projectionId": "$item.projectionId",
                "projectionFailed": true,
                "failure": "$steps.failProjection"
            }
        }
    },
    {
        "id": "disputeProjections",
        "forEach": {
            "items": "$steps.providerRun.disputes",
            "max": 5,
            "continueOnError": true,
            "steps": [
                {
                    "id": "commerceDispute",
                    "call": {
                        "source": "{{dependencies.commerce.sourceId}}",
                        "endpoint": "recordOrderStripeDispute",
                        "body": {
                            "orderPublicId": "$item.clientReferenceId",
                            "providerEventId": "$item.providerEventId",
                            "providerDisputeId": "$item.id",
                            "status": "$item.status",
                            "reason": "$item.reason",
                            "amount": "$item.amount",
                            "currency": "$item.currency",
                            "openedAt": "$item.createdAt",
                            "occurredAt": "$item.updatedAt",
                            "evidenceDueBy": "$item.evidenceDueBy",
                            "providerSnapshot": "$item"
                        }
                    }
                },
                {
                    "id": "acknowledgeDisputeProjection",
                    "call": {
                        "source": "{{dependencies.stripe.sourceId}}",
                        "endpoint": "acknowledgeCommerceProjection",
                        "body": {
                            "projectionId": "$item.projectionId",
                            "claimToken": "$item.projectionClaimToken"
                        }
                    }
                }
            ],
            "yield": "$steps.commerceDispute",
            "onError": [
                {
                    "id": "failDisputeProjection",
                    "call": {
                        "source": "{{dependencies.stripe.sourceId}}",
                        "endpoint": "failCommerceProjection",
                        "body": {
                            "projectionId": "$item.projectionId",
                            "claimToken": "$item.projectionClaimToken",
                            "error": "Commerce dispute projection failed"
                        }
                    }
                }
            ],
            "errorYield": {
                "projectionId": "$item.projectionId",
                "projectionFailed": true,
                "failure": "$steps.failDisputeProjection"
            }
        }
    }
]

[
    {
        "assert": {
            "condition": {
                "all": [
                    {
                        "gte": [
                            "$input.body.limit",
                            1
                        ]
                    },
                    {
                        "lte": [
                            "$input.body.limit",
                            5
                        ]
                    }
                ]
            },
            "failure": {
                "status": 400,
                "error": "limit must be between 1 and 5"
            }
        }
    },
    {
        "id": "platformLiabilities",
        "call": {
            "source": "{{dependencies.commerce.sourceId}}",
            "endpoint": "pendingPlatformPayoutLiabilityAuthorizations",
            "body": {
                "runKey": "$input.body.runKey"
            }
        }
    },
    {
        "id": "platformLiabilityApplications",
        "forEach": {
            "items": "$steps.platformLiabilities.authorizations",
            "max": 1,
            "steps": [
                {
                    "id": "providerControl",
                    "call": {
                        "source": "{{dependencies.stripe.sourceId}}",
                        "endpoint": "configurePlatformPayoutControls",
                        "body": {
                            "platformPayoutControlChangeId": {
                                "$concat": [
                                    "commerce-reconciliation:",
                                    "$input.body.runKey",
                                    ":",
                                    "$item.liabilityRevision"
                                ]
                            },
                            "minimumBalanceEur": "$item.requiredMinimumAmount",
                            "liabilityRevision": "$item.liabilityRevision",
                            "decreaseAuthorizationId": "$item.decreaseAuthorizationId",
                            "reason": "Commerce aggregate liability reconciliation"
                        }
                    }
                },
                {
                    "id": "commerceReceipt",
                    "call": {
                        "source": "{{dependencies.commerce.sourceId}}",
                        "endpoint": "recordPlatformPayoutLiabilityApplied",
                        "body": {
                            "liabilityRevision": "$steps.providerControl.liabilityRevision",
                            "appliedMinimumAmount": "$steps.providerControl.appliedMinimumBalanceEur",
                            "decreaseAuthorizationId": "$steps.providerControl.decreaseAuthorizationId"
                        }
                    }
                }
            ],
            "yield": {
                "authorization": "$item",
                "provider": "$steps.providerControl",
                "receipt": "$steps.commerceReceipt"
            }
        }
    },
    {
        "id": "providerRun",
        "call": {
            "source": "{{dependencies.stripe.sourceId}}",
            "endpoint": "runProviderReconciliation",
            "body": {
                "runKey": "$input.body.runKey",
                "limit": "$input.body.limit"
            }
        }
    },
    {
        "$include": "payment-projections.json"
    }
]

