                    "EUR"
                ]
            },
            "failure": {
                "status": 409,
                "error": "Protected C2C payments currently support EUR only"
            }
        }
    },
    {
        "assert": {
            "condition": {
                "gt": [
                    "$steps.terms.buyerTotalAmount",
                    0
                ]
            },
            "failure": {
                "status": 409,
                "error": "Order total must be positive"
            }
        }
    }
]

{
    "type": "function",
    "function": {
        "id": "executeProviderPaymentCancellation",
        "method": "POST",
        "access": {
            "mode": "system"
        },
        "meta": {
            "name": "Execute provider payment cancellation",
            "description": "Cancel or reconcile one Stripe PaymentIntent before Commerce restores inventory."
        },
        "input": {
            "body": {
                "type": "object",
                "properties": {
                    "status": {
                        "type": "string"
                    },
                    "paymentCancellationRequestId": {
                        "type": "number"
                    },
                    "cancellationRequestId": {
                        "type": "string"
                    },
                    "orderId": {
                        "type": "number"
                    },
                    "orderPublicId": {
                        "type": "string"
                    },
                    "clientReferenceId": {
                        "type": "string"
                    },
                    "targetOrderStatus": {
                        "type": "string"
                    },
                    "reason": {
                        "type": "string"
                    },
                    "amount": {
                        "type": "number"
                    },
                    "currency": {
                        "type": "string"
                    },
                    "financialTermsHash": {
                        "type": "string"
                    }
                },
                "required": [
                    "status",
                    "paymentCancellationRequestId",
                    "cancellationRequestId",
                    "orderId",
                    "orderPublicId",
                    "clientReferenceId",
                    "targetOrderStatus",
                    "reason",
                    "amount",
                    "currency",
                    "financialTermsHash"
