{
    "id": "executeAuthorizedRefund",
    "method": "POST",
    "access": {
        "mode": "system"
    },
    "meta": {
        "name": "Execute authorized refund",
        "description": "Execute Commerce-authorized seller recovery and buyer refund operations in provider order."
    },
    "input": {
        "body": {
            "type": "object",
            "properties": {
                "status": {
                    "type": "string"
                },
                "orderId": {
                    "type": "number"
                },
                "orderPublicId": {
                    "type": "string"
                },
                "providerPaymentId": {
                    "type": "number"
                },
                "refundRequestId": {
                    "type": "string"
                },
                "commerceRefundRequestId": {
                    "type": "number"
                },
                "businessKey": {
                    "type": "string"
                },
                "amount": {
                    "type": "number"
                },
                "authorizedSellerAmount": {
                    "type": "number"
                },
                "sellerEntitlementReductionAmount": {
                    "type": "number"
                },
                "sellerRecoveryAmount": {
                    "type": "number"
                },
                "protectionFeeRefundAmount": {
                    "type": "number"
                },
                "currency": {
                    "type": "string"
                },
                "financialTermsHash": {
                    "type": "string"
                },
                "requiresFinanceApproval": {
                    "type": "boolean"
                }
            },
            "required": [
                "status",
                "orderId",
                "orderPublicId",
                "providerPaymentId",
                "refundRequestId",
                "commerceRefundRequestId",
                "businessKey",
                "amount",
                "authorizedSellerAmount",
                "sellerEntitlementReductionAmount",
                "sellerRecoveryAmount",
                "protectionFeeRefundAmount",
                "currency",
                "financialTermsHash",
                "requiresFinanceApproval"
            ]
        }
    },
    "output": [
        {
            "status": "200",
            "body": {
                "type": "object"
            }
        }
    ],
    "steps": {
        "$include": "steps.json"
    },
    "return": {
        "status": 200,
        "body": {
            "orderPublicId": "$input.body.orderPublicId",
            "providerRefund": "$steps.providerRefund",
            "commerceOperations": "$steps.commerceOperations"
        }
    }
}

[
    {
        "assert": {
            "condition": {
                "in": [
                    "$input.body.status",
                    [
                        "approved",
                        "provider_operation_reserved",
                        "processing"
                    ]
                ]
            },
            "failure": {
                "status": 409,
                "error": "Refund is not fully authorized"
            }
        }
    },
    {
        "id": "providerRefund",
        "call": {
            "source": "{{dependencies.stripe.sourceId}}",
            "endpoint": "requestProtectedRefund",
            "body": {
                "paymentId": "$input.body.providerPaymentId",
                "refundRequestId": "$input.body.refundRequestId",
                "commerceRefundRequestId": "$input.body.commerceRefundRequestId",
                "amount": "$input.body.amount",
                "authorizedSellerAmount": "$input.body.authorizedSellerAmount",
                "sellerEntitlementReductionAmount": "$input.body.sellerEntitlementReductionAmount",
                "reason": "Commerce authorized refund"
            }
        }
    },
    {
        "id": "commerceOperations",
        "forEach": {
            "items": "$steps.providerRefund.operations",
            "max": 24,
            "steps": [
                {
                    "id": "commerceOperation",
                    "call": {
                        "source": "{{dependencies.commerce.sourceId}}",
                        "endpoint": "recordOrderSettlement",
                        "body": {
                            "orderPublicId": "$input.body.orderPublicId",
                            "providerEventId": {
                                "$concat": [
                                    "provider-operation:",
                                    "$item.providerOperationId",
                                    ":",
                                    "$item.status",
                                    ":",
                                    "$item.occurredAt"
                                ]
                            },
                            "operationType": "$item.operationType",
                            "providerOperationId": "$item.providerOperationId",
                            "status": "$item.status",
                            "amount": "$item.amount",
                            "currency": "$item.currency",
                            "occurredAt": "$item.occurredAt",
                            "refundRequestId": "$input.body.refundRequestId",
                            "commerceRefundRequestId": "$input.body.commerceRefundRequestId",
                            "providerSnapshot": "$item.providerSnapshot"
                        }
                    }
                }
            ],
            "yield": "$steps.commerceOperation"
        }
    }
]

definitions/artifacts/functions/settleme.content:
{
    "type": "function",
    "function": {
        "id": "applyPlatformPayoutLiabilityDecrease",
        "method": "POST",
        "access": {
            "mode": "admin"
        },
        "meta": {
            "name": "Apply platform payout liability decrease",
            "description": "Authorize one exact current Commerce aggregate revision, apply it to Stripe, and persist the provider receipt with CAS."
        },
        "input": {
            "body": {
                "type": "object",
                "properties": {
                    "expectedLiabilityRevision": {
                        "type": "number"
                    },
                    "reason": {
                        "type": "string"
                    }
                },
                "required": [
                    "expectedLiabilityRevision",
                    "reason"
                ]
            }
        },
        "output": [
            {
                "status": "200",
                "body": {
                    "type": "object"
                }
            }
        ],
        "steps": [
            {
                "id": "authorization",
                "call": {
                    "source": "{{dependencies.commerce.sourceId}}",
                    "endpoint": "authorizePlatformPayoutLiabilityDecrease",
                    "body": {
                        "expectedLiabilityRevision": "$input.body.expectedLiabilityRevision",
                        "reason": "$input.body.reason"
                    }
                }
            },
            {
                "id": "provider",
                "call": {
                    "source": "{{dependencies.stripe.sourceId}}",
                    "endpoint": "configurePlatformPayoutControls",
                    "body": {
                        "platformPayoutControlChangeId": {
                            "$concat": [
                                "commerce-finance-decrease:",
                                "$steps.authorization.liabilityRevision",
                                ":",
                                "$steps.authorization.decreaseAuthorizationId"
                            ]
                        },
                        "minimumBalanceEur": "$steps.authorization.requiredMinimumAmount",
                        "liabilityRevision": "$steps.authorization.liabilityRevision",
                        "decreaseAuthorizationId": "$steps.authorization.decreaseAuthorizationId",
                        "reason": "$input.body.reason"
                    }
                }
            },
            {
                "id": "receipt",
                "call": {
                    "source": "{{dependencies.commerce.sourceId}}",
                    "endpoint": "recordPlatformPayoutLiabilityApplied",
                    "body": {
                        "liabilityRevision": "$steps.provider.liabilityRevision",
                        "appliedMinimumAmount": "$steps.provider.appliedMinimumBalanceEur",
                        "decreaseAuthorizationId": "$steps.provider.decreaseAuthorizationId"
                    }
                }
            },
            {
                "assert": {
                    "condition": {
                        "equals": [
                            "$steps.receipt.accepted",
                            true
                        ]
                    },
                    "failure": {
                        "status": 409,
                        "error": "A newer Commerce liability revision won; reapply the current revision"
                    }
                }
            }
        ],
        "return": {
            "status": 200,
            "body": {
                "authorization": "$steps.authorization",
                "provider": "$steps.provider",
                "receipt": "$steps.receipt"
            }
        }
    }
}

{
    "id": "executeAuthorizedSettlementRelease",
    "method": "POST",
    "access": {
        "mode": "system"
    },
    "meta": {
        "name": "Execute authorized settlement release",
        "description": "Execute one immutable Commerce release authorization and report Stripe provider truth."
    },
    "input": {
        "body": {
            "type": "object",
            "properties": {
                "status": {
                    "type": "string"
                },
                "releaseAuthorizationId": {
                    "type": "string"
                },
                "orderId": {
                    "type": "number"
                },
                "orderPublicId": {
                    "type": "string"
                },
                "paymentId": {
                    "type": "number"
                },
                "businessKey": {
                    "type": "string"
                },
                "releaseKind": {
                    "type": "string"
                },
                "sellerId": {
                    "type": "string",
                    "semantic": {
                        "kind": "user-id",
                        "authority": "cms"
                    }
                },
                "sellerRequiredMinimumBalanceAmount": {
                    "type": "number"
                },
                "payoutDelayDays": {
                    "type": "number"
                },
                "amount": {
                    "type": "number"
                },
                "currency": {
                    "type": "string"
                },
                "financialTermsHash": {
                    "type": "string"
                }
            },
            "required": [
                "status",
                "releaseAuthorizationId",
                "orderId",
                "orderPublicId",
                "paymentId",
                "businessKey",
                "releaseKind",
                "sellerId",
                "sellerRequiredMinimumBalanceAmount",
                "payoutDelayDays",
                "amount",
                "currency",
                "financialTermsHash"
            ]
        }
    },
    "output": [
        {
            "status": "200",
            "body": {
                "type": "object"
            }
        }
    ],
    "steps": {
        "$include": "steps.json"
    },
    "return": {
        "status": 200,
        "body": {
            "orderPublicId": "$input.body.orderPublicId",
            "providerTransfer": "$steps.providerTransfer",
            "commerceSettlement": "$steps.commerceSettlement"
        }
    }
}

[
    {
        "assert": {
            "condition": {
                "equals": [
                    "$input.body.status",
                    "authorized"
                ]
            },
            "failure": {
                "status": 409,
                "error": "Settlement release is not authorized"
            }
        }
    },
    {
        "id": "sellerPayoutControls",
        "call": {
            "source": "{{dependencies.stripe.sourceId}}",
            "endpoint": "configureSellerPayoutSchedule",
            "body": {
                "userId": "$input.body.sellerId",
                "payoutScheduleChangeId": {
                    "$concat": [
                        "settlement-release:",
                        "$input.body.releaseAuthorizationId",
                        ":",
                        "$input.body.sellerRequiredMinimumBalanceAmount",
                        ":",
                        "$input.body.payoutDelayDays",
                        ":",
                        "{{answers.sellerPayoutSchedule}}"
                    ]
                },
                "payoutSchedule": "{{answers.sellerPayoutSchedule}}",
                "minimumBalanceEur": "$input.body.sellerRequiredMinimumBalanceAmount",
                "delayDaysOverride": "$input.body.payoutDelayDays",
                "reason": "Commerce authorized settlement release"
            }
        }
    },
    {
        "id": "providerTransfer",
        "call": {
            "source": "{{dependencies.stripe.sourceId}}",
            "endpoint": "requestSettlementRelease",
            "body": {
                "paymentId": "$input.body.paymentId",
                "releaseAuthorizationId": "$input.body.releaseAuthorizationId",
                "releaseKind": "$input.body.releaseKind",
                "amount": "$input.body.amount",
                "currency": "$input.body.currency"
            }
        }
    },
    {
        "id": "commerceSettlement",
        "call": {
            "source": "{{dependencies.commerce.sourceId}}",
            "endpoint": "recordOrderSettlement",
            "body": {
                "orderPublicId": "$input.body.orderPublicId",
                "providerEventId": {
                    "$concat": [
                        "transfer:",
                        "$steps.providerTransfer.providerOperationId",
                        ":",
                        "$steps.providerTransfer.updatedAt"
                    ]
                },
                "operationType": "transfer",
                "providerOperationId": "$steps.providerTransfer.providerOperationId",
                "status": "$steps.providerTransfer.status",
                "amount": "$steps.providerTransfer.amount",
                "currency": "$steps.providerTransfer.currency",
                "occurredAt": "$steps.providerTransfer.occurredAt",
                "releaseAuthorizationId": "$input.body.releaseAuthorizationId",
                "providerSnapshot": "$steps.providerTransfer"
            }
        }
    }
]

